import {createWorkspace} from './src/workspace.js';
import {createDraftStore} from './src/draft-store.js';
import {createReceiptArchive} from './src/receipt-archive.js';
const jobs = new Map(); let serial=0;
const timers={schedule(fn,delay){assert.equal(delay,120); const id=++serial;jobs.set(id,fn);return id},cancel(id){jobs.delete(id)}};
const tick=()=>{for(const [id,fn] of [...jobs]){jobs.delete(id);fn()}};
const store=createDraftStore(); const archive=createReceiptArchive(); const docs=[],statuses=[],notices=[];
