workspace.open('a'); workspace.edit('one');workspace.edit('two');assert.equal(store.read('a'),'');tick();assert.equal(store.read('a'),'two');assert.equal(statuses.length,1);
workspace.edit('three');tick();assert.equal(store.read('a'),'three');assert.equal(statuses.length,2);
workspace.edit('four');workspace.close();assert.equal(store.read('a'),'four');assert.equal(jobs.size,0);
workspace.open('a');assert.equal(docs.at(-1).text,'four');workspace.edit('five');const receipt=workspace.submit();assert.deepEqual(receipt,{id:'a',text:'five'});assert.equal(store.read('a'),'five');assert.equal(notices.at(-1),receipt);
workspace.edit('six');workspace.open('b');assert.equal(store.read('a'),'six');assert.equal(statuses.length,4);
workspace.dispose();
console.log('controlled timer lifecycle checks passed');
EOF"

